// The SDK in sdk/typescript was generated by APIMatic from openapi.yaml. These check that its models read what the real
// routes answer, so a change to an answer that the SDK can't read fails here, before anyone using the SDK finds it.
import { readFileSync } from "node:fs";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { pullRecalls } from "@/server/cpsc/pull";
import { migrate } from "@/server/db/migrate";
import type { Queryable } from "@/server/db/types";
import { getHealth } from "@/server/health";
import { withIntegrations } from "@/server/integrations";
import { testDb } from "@/test/pglite";
import { checkAnswerSchema } from "../sdk/typescript/src/models/check-answer";
import { healthSchema } from "../sdk/typescript/src/models/health";
import { publicRecallSchema } from "../sdk/typescript/src/models/public-recall";

let db: Queryable;
vi.mock("@/server/db/pg", () => ({ getDb: () => db }));
import { GET } from "@/app/api/check/route";
import { GET as readRecall } from "@/app/api/recalls/[recallNumber]/route";

const fixtureText = readFileSync(new URL("../test/fixtures/cpsc/recalls_2026-10-01_to_2026-11-05.json", import.meta.url), "utf8");

describe("the generated SDK reads the real answers", () => {
  let real: Awaited<ReturnType<typeof testDb>>;
  beforeEach(async () => {
    real = await testDb();
    await migrate(real);
    db = real;
    const fetchImpl = async () => new Response(fixtureText, { status: 200, headers: { "content-type": "application/json" } });
    await pullRecalls(real, { field: "RecallDate", start: "2026-10-01", end: "2026-11-05" }, { fetchImpl: fetchImpl as typeof fetch });
  });
  afterEach(async () => {
    await real.close();
  });

  const check = async (query: string) => (await GET(new Request(`http://localhost/api/check?${query}`, { headers: { "true-client-ip": "198.51.100.9" } }))).json();

  it.each(["title=Baby+Brezza+sterilizer&model=BRZ0083", "title=Baby+Brezza", "title=Costway+high+chair", "title=zzqx+vvbn+plmk"])("check, for %s", async (query) => {
    const answer = await check(query);
    const read = checkAnswerSchema.decode(answer);
    expect(read.results.map((r) => r.recallNumber)).toEqual(answer.results.map((r: { recallNumber: string }) => r.recallNumber));
    expect(read.mentioned.total).toBe(answer.mentioned.total);
  });

  it("reads one recall by its number", async () => {
    const res = await readRecall(new Request("http://localhost/api/recalls/27072", { headers: { "true-client-ip": "198.51.100.10" } }), { params: Promise.resolve({ recallNumber: "27072" }) });
    expect(res.status).toBe(200);
    const read = publicRecallSchema.decode(await res.json());
    expect(read.found).toBe(true);
    expect(read.recallNumber).toBe("27072");
  });

  it("refuses an answer missing a field the SDK needs", async () => {
    const answer = await check("title=Baby+Brezza");
    delete answer.mentioned;
    expect(() => checkAnswerSchema.decode(answer)).toThrow();
  });

  it("health", async () => {
    // What the route sends: getHealth plus the integration rows (no GitHub call in a test).
    const health = await withIntegrations(real, await getHealth(real, { PAYPAL_WEBHOOK_ID: "x", RECORD_HMAC_SECRET: "r".repeat(32) }), {}, { newman: async () => null });
    const read = healthSchema.decode(JSON.parse(JSON.stringify(health)));
    expect(read.paypal?.environment).toBe("sandbox");
    expect(read.integrations.rows.length).toBe(read.integrations.summary.of);
  });
});
